const el=document.getElementById('projects');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const rows=projects.map((p,i)=>({...p,index:i+1}));
el.innerHTML=rows.map(p=>`<details><summary><span class="num">${String(p.index).padStart(2,'0')}</span><span><span class="name">${escapeHTML(p.name)}${p.featured?'<span class="badge active" title="Shown on the portfolio">Active</span>':'<span class="badge inactive" title="Not shown on the portfolio">Inactive</span>'}</span><span class="hint">${escapeHTML(p.client)} · ${escapeHTML(p.hook)}</span></span><span class="plus" aria-hidden="true">+</span></summary><div class="body"><p>${escapeHTML(p.detail)}</p><p><span class="label">Contribution / recall note</span>${escapeHTML(p.role)}</p><p class="note">Source review: ${escapeHTML(p.status)}. Reviews cover representative artifacts, not every frame.</p>${p.image?`<a href="${p.image}" target="_blank" rel="noopener"><img src="${p.image}" alt="${escapeHTML(p.name)} portfolio reference image" loading="lazy"></a>`:''}<div class="links">${p.page?`<a href="../${p.page}">${p.featured?'Portfolio case':'Project reference'} ↗</a>`:''}${p.live?`<a href="${escapeHTML(p.live)}" target="_blank" rel="noopener noreferrer">Public reference ↗</a>`:''}</div></div></details>`).join('');
document.getElementById('count').textContent=`${rows.length} of ${projects.length} entries · related work grouped`;document.getElementById('empty').hidden=rows.length!==0;}
document.getElementById('collapse').addEventListener('click',()=>document.querySelectorAll('details[open]').forEach(d=>d.open=false));render();
